from datetime import datetime, timedelta
def matches(text, value):
    return text == '*' or str(value) in text.split(',')
def next_run(fields, t):
    while True:
        t += timedelta(minutes=1)
        now = (t.minute, t.hour, t.isoweekday() % 7)
        if all(map(matches, fields, now)):
            return t
start = datetime(2026, 10, 13, 9, 30)
fmt = '%Y-%m-%d %H:%M %a'
print(next_run(('30', '9', '1,2,3,4,5'), start).strftime(fmt))
print(next_run(('0', '0', '5'), start).strftime(fmt))

